     /// Inserts a value, evicting the least-recently-used entry if at capacity.
     ///
     /// # Parameters
     ///
     /// - `key`: The cache key to insert or update.
     /// - `value`: The value to store.
     ///
     #[verus_verify(external_body)]
     #[verus_spec(
         requires
             old(self)@.inv(),
         ensures
             self@ == old(self)@.spec_put(key, value),
             self@.inv(),
             self@.capacity == old(self)@.capacity,
             // Put-get round-trip: if capacity > 0, the key is now present.
             old(self)@.capacity > 0 ==> {
                 &&& self@.contents.dom().contains(key)
                 &&& self@.contents[key] == value
             },
             // Zero-capacity no-op.
             old(self)@.capacity == 0 ==> self@ == old(self)@,
     )]
     pub fn put(&mut self, key: K, value: V) {
         // A zero-capacity cache cannot store entries.
         if self.capacity == 0 {
             return;
         }

         // If the key is already present, update in place.
         if let Some(entry) = self.entries.get_mut(&key) {
             self.counter += 1;
             entry.value = value;
             entry.last_used = self.counter;
             return;
         }

         // Evict the LRU entry if at capacity.
         if self.entries.len() >= self.capacity {
             self.evict();
         }

         self.counter += 1;
         self.entries.insert(
             key,
