//! Bounded LRU cache backed by `BTreeMap`.
//!
//! Entries are stored in a `BTreeMap` keyed by a caller-chosen type `K` that
//! implements `Ord + Clone`. A monotonic counter tracks access order; on
//! eviction the entry with the smallest (oldest) counter value is removed.
//! Lookups bump the counter to mark the entry as recently used.

#![cfg_attr(not(feature = "std"), no_std)]
#![cfg_attr(verus_keep_ghost, feature(proc_macro_hygiene))]
#![cfg_attr(verus_keep_ghost, feature(allocator_api))]

extern crate alloc;

use ::alloc::collections::BTreeMap;
use ::core::ops::{Deref, DerefMut};

use vstd::prelude::*;
#[cfg(verus_keep_ghost)]
include!("lib.spec.rs");
#[cfg(verus_keep_ghost)]
include!("lib.proof.rs");

/// A single entry in the cache.
#[derive(Clone)]
struct CacheEntry<V> {
    value: V,
    last_used: u64,
}

pub struct CacheGuard<'a, V> {
    value: &'a mut V,
}

impl<V> Deref for CacheGuard<'_, V> {
    type Target = V;
    fn deref(&self) -> &V {
        self.value
    }
}

impl<V> DerefMut for CacheGuard<'_, V> {
    fn deref_mut(&mut self) -> &mut V {
        self.value
    }
}

#[verus_verify(reject_recursive_types(K))]
#[verus_verify(reject_recursive_types(V))]
pub struct Cache<K, V> {
    entries: BTreeMap<K, CacheEntry<V>>,
    counter: u64,
    capacity: usize,
}

#[verus_verify]
impl<K: Ord + Clone, V> Cache<K, V> {
    #[verus_verify(external_body)]
    #[verus_spec(result =>
        ensures
            result@ == CacheView::<K, V>::spec_new(capacity as nat),
            result@.inv(),
            result@.contents == Map::<K, V>::empty(),
            result@.capacity == capacity as nat,
            result@.lru_order == Seq::<K>::empty(),
    )]
    pub const fn new(capacity: usize) -> Self {
        Self {
            entries: BTreeMap::new(),
            counter: 0,
            capacity,
        }
    }

    #[verus_verify(external_body)]
    #[verus_spec(result =>
        requires
            old(self)@.inv(),
        ensures
            // Hit: key is present.
            old(self)@.contents.dom().contains(*key) ==> {
                &&& result is Some
                &&& self@ == old(self)@.spec_get(*key).0
                &&& self@.contents == old(self)@.contents
                &&& self@.capacity == old(self)@.capacity
                &&& self@.inv()
            },
            // Miss: key is absent.
            !old(self)@.contents.dom().contains(*key) ==> {
                &&& result is None
                &&& self@ == old(self)@
            },
    )]
    pub fn get(&mut self, key: &K) -> Option<CacheGuard<'_, V>> {
        if let Some(entry) = self.entries.get_mut(key) {
            self.counter += 1;
            entry.last_used = self.counter;
            Some(CacheGuard { value: &mut entry.value })
        } else {
            None
        }
    }

    #[verus_verify(external_body)]
    #[verus_spec(
        requires
            old(self)@.inv(),
        ensures
            self@ == old(self)@.spec_put(key, value),
            self@.inv(),
            self@.capacity == old(self)@.capacity,
            // Put-get round-trip: if capacity > 0, the key is now present.
            old(self)@.capacity > 0 ==> {
                &&& self@.contents.dom().contains(key)
                &&& self@.contents[key] == value
            },
            // Zero-capacity no-op.
            old(self)@.capacity == 0 ==> self@ == old(self)@,
    )]
    pub fn put(&mut self, key: K, value: V) {
        if self.capacity == 0 { return; }
        if let Some(entry) = self.entries.get_mut(&key) {
            self.counter += 1;
            entry.value = value;
            entry.last_used = self.counter;
            return;
        }
        if self.entries.len() >= self.capacity {
            self.evict();
        }
        self.counter += 1;
        self.entries.insert(key, CacheEntry { value, last_used: self.counter });
    }

    #[verus_verify(external_body)]
    #[verus_spec(
        requires
            old(self)@.inv(),
        ensures
            self@ == old(self)@.spec_remove(*key),
            self@.inv(),
            self@.capacity == old(self)@.capacity,
            // Key is no longer present.
            !self@.contents.dom().contains(*key),
            // Key absent: no-op.
            !old(self)@.contents.dom().contains(*key) ==> self@ == old(self)@,
    )]
    pub fn remove(&mut self, key: &K) {
        self.entries.remove(key);
    }

    #[verus_verify(external_body)]
    #[verus_spec(
        requires
            old(self)@.inv(),
        ensures
            self@ == old(self)@.spec_clear(),
            self@.inv(),
            self@.contents == Map::<K, V>::empty(),
            self@.lru_order == Seq::<K>::empty(),
            self@.capacity == old(self)@.capacity,
    )]
    pub fn clear(&mut self) {
        self.entries.clear();
        self.counter = 0;
    }

    #[verus_verify(external_body)]
    #[verus_spec(
        requires
            old(self)@.inv(),
            old(self)@.contents.dom().len() > 0,
        ensures
            !self@.contents.dom().contains(old(self)@.lru_order[0]),
            self@.contents == old(self)@.contents.remove(old(self)@.lru_order[0]),
            self@.contents.dom().len() == old(self)@.contents.dom().len() - 1,
            self@.lru_order == old(self)@.lru_order.subrange(1, old(self)@.lru_order.len() as int),
            self@.capacity == old(self)@.capacity,
            self@.inv(),
    )]
    fn evict(&mut self) {
        let victim: Option<K> = self
            .entries
            .iter()
            .min_by_key(|(_, e)| e.last_used)
            .map(|(k, _)| k.clone());
        if let Some(key) = victim {
            self.entries.remove(&key);
        }
    }
}
