138.     pub async fn run(
139.         &mut self,
140.         tenant_id: Option<&str>,
141.         app_name: Option<&str>,
142.         guest_binary_path: &str,
143.         guest_binary_args: &str,
144.     ) -> Result<i32> {
145.         let sandbox_cache: Arc<SandboxCache<T>> = SandboxCache::new(self.config.clone()).await?;
146.         let mut signals: Signal = signal(SignalKind::interrupt())?;
147. 
148.         let tenant_id: String = match tenant_id {
149.             Some(s) => s.to_owned(),
150.             None => Self::get_current_user_name()?,
151.         };
152.         let app_name: String = app_name
153.             .map(|s| s.to_owned())
154.             .unwrap_or_else(|| DEFAULT_APP_NAME.to_owned());
155.         let (uservm_id, gateway_sockaddr, gateway_socket_type): (
156.             UserVmIdentifier,
157.             String,
158.             SocketType,
159.         ) = sandbox_cache
160.             .get(
161.                 &tenant_id,
162.                 guest_binary_path,
163.                 &app_name,
164.                 if guest_binary_args.is_empty() {
165.                     None
166.                 } else {
167.                     Some(guest_binary_args.to_string())
168.                 },
169.             )
170.             .await?;
171. 
172.         let gateway_stream: SocketStream = UnboundSocket::new(gateway_socket_type)
173.             .connect(&gateway_sockaddr)
174.             .await?;
175. 
176.         // Create channel for stdin data.
177.         let (stdin_tx, mut stdin_rx): (UnboundedSender<Vec<u8>>, UnboundedReceiver<Vec<u8>>) =
178.             mpsc::unbounded_channel();
179. 
180.         // Create channel for EOF notification.
181.         let (eof_tx, mut eof_rx): (UnboundedSender<()>, UnboundedReceiver<()>) =
182.             mpsc::unbounded_channel();
183. 
184.         // Create channel for thread ID communication.
185.         let (thread_id_tx, mut thread_id_rx): (UnboundedSender<u64>, UnboundedReceiver<u64>) =
186.             mpsc::unbounded_channel();
187. 
188.         // Spawn a dedicated thread for blocking stdin reads. We use a separate thread because
189.         // tokio's async stdin handling is not suitable for standard blocking stdin reads.
190.         // Furthermore, we don't join this thread because it should run for the entire duration of
191.         // the terminal session.
192.         let _stdin_handle: ::std::thread::JoinHandle<()> = ::std::thread::spawn(move || {
193.             Self::stdin_thread(stdin_tx, thread_id_tx, eof_tx);
194.         });
195. 
