197.         let stdin_thread_id: u64 = thread_id_rx.recv().await.ok_or_else(|| {
198.             let reason: &str = "failed to receive id of stdin thread";
199.             error!("{reason}");
200.             anyhow::anyhow!(reason)
201.         })?;
202. 
203.         let mut stdout: Stdout = io::stdout();
204.         let mut gateway_buffer: [u8; IO_BUFFER_SIZE] = [0; IO_BUFFER_SIZE];
